import{z as o,x as p,o as s,c as B,q as r,j as i,D as t,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"影子页表","description":"","frontmatter":{"title":"影子页表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shadow-page-table.md","filePath":"cs/shadow-page-table.md","lastUpdated":1791413859000}'),d={name:"cs/shadow-page-table.md"};function P(T,a,m,c,h,D){const A=p("Mermaid");return s(),B("div",null,[a[2]||(a[2]=r('<h1 id="影子页表" tabindex="-1">影子页表 <a class="header-anchor" href="#影子页表" aria-label="Permalink to &quot;影子页表&quot;">​</a></h1><div class="epigraph"><p>没有 EPT 时，VMM 维护影子页表：客户 VA→宿主 PA，客户改 CR3/pte 要退出同步；有 EPT 则硬件走两维翻译。</p><footer>—— 据 Adams and Agesen 对软件 MMU 的论述；Intel EPT；[分页](/cs/demand-paging) 为先修</footer></div><p><a href="/cs/vmx-vmexit">VM-exit</a> 的大户曾是页表。<a href="/cs/rmap">rmap</a> 是宿主。缺口是 <strong>影子 vs EPT</strong>：嵌套页表如何减少 exit。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>客户以为自己管 PA。实际 GPA 要到 HPA。影子：VMM 把客户页表「编译」成一份给硬件的表。EPT：硬件 gva→gpa→hpa。缺口：缺页：客户缺页 vs EPT 缺页（需 VMM 补宿主页）。本课不把 NPT 字段写完。</p><p><span class="marginnote">大页 THP 在 EPT 上也有对应。对象是翻译，不是客户 malloc。</span></p><p><span class="marginnote">直觉类比：影子页图像一家翻译公司替你把整本书译好——客户每改一页原文（改一条 pte），公司都得重译并送印；EPT 则像给读者配了本双语词典，硬件边读边翻，作者改稿不必惊动任何人。前者的开销全在「改稿同步」上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无 EPT：拦截客户页表写。有 EPT：建 EPT 树，客户 CR3 仍是 GPA。对照 <a href="/cs/kpti-os">KPTI</a>：都是多套页表，目的不同。对照 <a href="/cs/dma-coherence">IOMMU</a>：设备翻译第三维，后课 VFIO。</p>',9)),(s(),i(n,null,{default:t(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GVA%5B%22%E5%AE%A2%E6%88%B7%E8%99%9A%E5%9D%80%22%5D%20--%3E%20GPT%5B%22%E5%AE%A2%E6%88%B7%E9%A1%B5%E8%A1%A8%20GPA%22%5D%0A%20%20GPT%20--%3E%20EPT%5B%22EPT%2FNPT%20%E5%88%B0%20HPA%22%5D%0A%20%20SH%5B%22%E5%BD%B1%E5%AD%90%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20HPA%5B%22%E7%9B%B4%E6%8E%A5%20GVA%20%E5%88%B0%20HPA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("EPT 把 MMU 虚拟化从「每次改 pte 都 exit」变成硬件走两层，是内存虚拟化的分水岭。影子仍用于无硬件或特殊调试。不要写成 CPU TLB 微架构课。与 "),E("a",{href:"/cs/memcg"},"memcg"),e("：宿主页仍 charge QEMU。")],-1)),a[5]||(a[5]=E("p",null,"换页：客户 swap 与宿主 swap 叠两层，会很惨。",-1)),(s(),i(n,null,{default:t(()=>[l(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22EPT%20%E8%BF%9D%E4%BE%8B%E8%A7%A6%E5%8F%91%20VM-exit%22%5D%20--%3E%20Q%7B%22%E8%AF%A5%20GPA%20%E5%AE%BF%E4%B8%BB%E6%9C%89%E6%98%A0%E5%B0%84%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%97%A0%7C%20H%5B%22VMM%20%E8%A1%A5%E5%AE%BF%E4%B8%BB%E9%A1%B5%E4%B8%8E%20EPT%20%E9%A1%B9%E5%90%8E%E9%87%8D%E8%B7%91%22%5D%0A%20%20Q%20--%3E%7C%E6%9C%89%7C%20Q2%7B%22%E5%AE%A2%E6%88%B7%E9%A1%B5%E8%A1%A8%E6%98%A0%E5%B0%84%E4%BA%86%E8%AF%A5%20GVA%3F%22%7D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20G%5B%22%E7%9C%9F%E7%BC%BA%E9%A1%B5%3A%20%E6%B3%A8%E5%85%A5%E5%AE%A2%E6%88%B7%20OS%20%E8%87%AA%E8%A1%8C%E5%A4%84%E7%90%86%22%5D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20P%5B%22%E6%9D%83%E9%99%90%E5%86%B2%E7%AA%81%2C%20%E5%A6%82%E5%86%99%E5%8F%AA%E8%AF%BB%E9%A1%B5%22%5D%0A%20%20P%20--%3E%20S%5B%22%E6%8C%89%E9%9C%80%E7%BD%AE%E4%BD%8D%E6%88%96%E9%99%8D%E6%9D%83%E5%90%8E%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：4 级客户页表套 4 级 EPT，一次 TLB 未命中最坏要走约 8 次内存访问。这就是大页对 EPT 特别值钱的原因——大页把两层各「压扁」一层，2MB 页下 8 次降到 6 次，1GB 页再各压一层到 4 次，缺页率还跟着降。</span></p><p><span class="marginnote">常见误区：初学者容易把「客户缺页」和「EPT 缺页」混为一谈。前者是客户 OS 的日常行为，客户自己换页解决，不该惊动 VMM；后者说明宿主根本没把那块物理内存分给它，必须 VMM 介入补映射。分类错了，本该在客户内部消化的缺页全变成 VM-exit，性能会崩。</span></p><p>实现上：EPT 违例分：客户该自己处理的缺页 vs 宿主还没映射 GPA。大页 EPT 能减 VM-exit。影子页表在客户频繁换 CR3 时同步成本高。 读法上只引用<a href="/cs/vmx-vmexit">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>影子页表</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入影子 paging 的全部优化（如跟踪脏）。不保证 RISC-V G 阶段细节。下一课减少 exit 的另一法：半虚拟化。</p><p>版本字段会变，课序钉的是机制对象「影子页表」，不是某一主线内核的结构体名。 后课默认：嵌套页表翻译 GPA。virtio 一类半虚拟接口，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子页表软件同步；EPT 硬件二维翻译。</li><li>缺页要分清客户与 EPT。</li><li>半虚拟化是下一课。</li><li>出处：Adams/Agesen；Intel EPT；KVM mmu。</li></ul>',10))])}const u=o(d,[["render",P]]);export{f as __pageData,u as default};
